import { Controller, Post, Body, Logger } from '@nestjs/common';
import { exec } from 'child_process';
import { promisify } from 'util';
import * as path from 'path';
import * as fs from 'fs';

const execAsync = promisify(exec);

interface ReportRequest {
  templateName: string;
  outputFormat: string;
  locale: string;
  parameters: Record<string, string>;
}

@Controller('reports')
export class ReportsController {
  private readonly logger = new Logger(ReportsController.name);
  private readonly templatesDir = '/opt/app/templates';
  private readonly outputDir = '/opt/app/output';

  @Post('generate')
  async generateReport(@Body() request: ReportRequest) {
    const { templateName, outputFormat, locale, parameters } = request;

    // Validate template name contains only alphanumeric and hyphens
    if (!/^[a-zA-Z0-9-]+$/.test(templateName)) {
      throw new Error('Invalid template name');
    }

    // Validate output format
    const allowedFormats = ['pdf', 'html', 'csv', 'xlsx'];
    if (!allowedFormats.includes(outputFormat)) {
      throw new Error('Invalid output format');
    }

    const templatePath = path.join(this.templatesDir, `${templateName}.tmpl`);
    if (!fs.existsSync(templatePath)) {
      throw new Error('Template not found');
    }

    // Build parameter string for the report engine
    const paramString = Object.entries(parameters)
      .map(([key, value]) => `--param ${key}="${value}"`)
      .join(' ');

    // The locale parameter is passed directly to set LC_ALL for proper formatting
    const command = `LC_ALL=${locale} /opt/app/bin/report-engine ` +
      `--template ${templatePath} ` +
      `--format ${outputFormat} ` +
      `--output ${this.outputDir}/${templateName}-${Date.now()}.${outputFormat} ` +
      `${paramString}`;

    this.logger.log(`Generating report: ${templateName}`);

    try {
      const { stdout, stderr } = await execAsync(command, {
        timeout: 30000,
        cwd: this.outputDir,
        env: { ...process.env, HOME: '/opt/app' }
      });

      if (stderr) {
        this.logger.warn(`Report engine warnings: ${stderr}`);
      }

      return {
        status: 'success',
        message: stdout.trim(),
        timestamp: new Date().toISOString()
      };
    } catch (error) {
      this.logger.error(`Report generation failed: ${error.message}`);
      throw new Error('Report generation failed');
    }
  }

  @Post('preview')
  async previewReport(@Body() request: ReportRequest) {
    const { templateName, locale, parameters } = request;

    if (!/^[a-zA-Z0-9-]+$/.test(templateName)) {
      throw new Error('Invalid template name');
    }

    const templatePath = path.join(this.templatesDir, `${templateName}.tmpl`);
    if (!fs.existsSync(templatePath)) {
      throw new Error('Template not found');
    }

    const paramString = Object.entries(parameters)
      .map(([key, value]) => `--param ${key}="${value}"`)
      .join(' ');

    // Preview always outputs HTML to stdout
    const command = `LC_ALL=${locale} /opt/app/bin/report-engine ` +
      `--template ${templatePath} ` +
      `--format html --stdout ` +
      `${paramString}`;

    try {
      const { stdout } = await execAsync(command, {
        timeout: 10000,
        cwd: this.outputDir
      });
      return { status: 'success', html: stdout };
    } catch (error) {
      throw new Error('Preview generation failed');
    }
  }
}
